<?php
namespace App\Models;
use App\Support\PermissionRegistry; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable;
class User extends Authenticatable { use SoftDeletes,Notifiable; protected $fillable=['name','email','password','role','locale','active']; protected $hidden=['password','remember_token']; protected $casts=['password'=>'hashed','active'=>'boolean']; public function employee():HasOne{return $this->hasOne(Employee::class);} public function permissionOverrides():HasMany{return $this->hasMany(UserPermissionOverride::class);} public function isHr():bool{return in_array($this->role,['company_admin','hr'],true);} public function hasPermission(string $permission):bool{if($this->role==='company_admin')return true;$override=$this->permissionOverrides()->where('permission',$permission)->value('allowed');if($override!==null)return (bool)$override;if($this->role==='hr')return (bool)(PermissionRegistry::hrDefaults()[$permission]??false);return false;} }
